int comedi_ioctl_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file) {
    struct comedi_devinfo info = {
        .version_code = dev->version_code,
        .n_subdev = dev->n_subdev,
        .read_subdev = -1,
        .write_subdev = -1
    };

    if (dev->n_subdev > 0) {
        for (int i = 0; i < dev->n_subdev; i++) {
            if (dev->subdevices[i].type == COMEDI_SUBD_AI)
                info.read_subdev = i;
            if (dev->subdevices[i].type == COMEDI_SUBD_AO)
                info.write_subdev = i;
        }
    }

    strncpy(info.driver_name, dev->driver->driver_name, sizeof(info.driver_name) - 1);
    info.driver_name[sizeof(info.driver_name) - 1] = '\0';

    strncpy(info.board_name, dev->board_name, sizeof(info.board_name) - 1);
    info.board_name[sizeof(info.board_name) - 1] = '\0';

    if (copy_to_user(arg, &info, sizeof(info)))
        return -EFAULT;

    return 0;
}
